1	// The phase-plan executor. See run_plan.hpp.
2	#include "run_plan.hpp"
3	
4	#include <cstdlib>
5	#include <filesystem>
6	
7	#include <unistd.h>
8	
9	#include "argv.hpp"
10	#include "process.hpp"
11	#include "repo_root.hpp"
12	#include "shm.hpp"
13	#include "state.hpp"
14	
15	namespace fs = std::filesystem;
16	
17	namespace andes_sim {
18	namespace {
19	
20	// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
21	std::string state_path(const std::string& workdir, size_t i) {
22	  return workdir + "/state-" + std::to_string(i) + ".bin";
23	}
24	
25	const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
26	                                    const std::string& id) {
27	  for (const EngineDescriptor& e : engines)
28	    if (e.id == id) return &e;
29	  return nullptr;
30	}
31	
32	// $VSIM_PLUGIN else the in-repo default (matches the e2e harness / hsim).
33	std::string resolve_plugin(const std::string& override_path) {
34	  if (!override_path.empty()) return override_path;
35	  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
36	  return default_plugin_path().string();
37	}
38	
39	}  // namespace
40	
41	std::vector<std::vector<std::string>> plan_argvs(
42	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
43	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
44	  std::vector<std::vector<std::string>> out;
45	  out.reserve(plan.steps.size());
46	  std::string prev_state_out;  // empty for the cold first leg
47	
48	  for (size_t i = 0; i < plan.steps.size(); ++i) {
49	    const Step& step = plan.steps[i];
50	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
51	    if (!eng) {
52	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
53	            step.engine_id + "'";
54	      return {};
55	    }
56	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
57	    if (!tmpl) {
58	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
59	            "' has no invoke template for role '" + step.role + "'";
60	      return {};
61	    }
62	
63	    const std::string state_out = state_path(workdir, i);
64	    const std::map<std::string, std::string> m = {
65	        {"bin", eng->bin_path},
66	        {"elf", plan.elf},
67	        {"plugin", ctx.plugin_path},
68	        {"mmap", ctx.mmap_path},
69	        {"mmap_size", std::to_string(ctx.mem_size)},
70	        {"mmap_base", ctx.mmap_base},
71	        {"state_in", prev_state_out},
72	        {"state_out", state_out},
73	    };
74	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
75	    if (!err.empty()) {
76	      err = "plan step " + std::to_string(i) + ": " + err;
77	      return {};
78	    }
79	    out.push_back(std::move(argv));
80	    prev_state_out = state_out;
81	  }
82	  err.clear();
83	  return out;
84	}
85	
86	PlanResult run_plan(const Plan& plan,
87	                    const std::vector<EngineDescriptor>& engines,
88	                    const PlanOptions& opts) {
89	  PlanResult res;
90	  if (plan.steps.empty()) {
91	    res.error = "plan has no steps";
92	    return res;
93	  }
94	
95	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
96	  std::string mmap_path = plan.mmap_path;
97	  const bool own_mmap = mmap_path.empty();
98	  if (own_mmap) {
99	    std::string err;
100	    mmap_path = allocate(plan.mem_size, err);
101	    if (mmap_path.empty()) {
102	      res.error = err;
103	      return res;
104	    }
105	  }
106	
107	  // A private dir for the threaded drain files.
108	  std::error_code ec;
109	  fs::path workdir = fs::temp_directory_path(ec) / "andes-sim-plan-XXXXXX";
110	  std::string tmpl = workdir.string();
111	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
112	  tbuf.push_back('\0');
113	  const char* made = ::mkdtemp(tbuf.data());
114	  if (!made) {
115	    if (own_mmap) ::unlink(mmap_path.c_str());
116	    res.error = "failed to create plan work dir";
117	    return res;
118	  }
119	  const std::string wd = made;
120	
121	  RuntimeCtx ctx;
122	  ctx.mmap_path = mmap_path;
123	  ctx.mem_size = plan.mem_size;
124	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
125	
126	  std::string err;
127	  const std::vector<std::vector<std::string>> argvs =
128	      plan_argvs(plan, engines, wd, ctx, err);
129	  if (!err.empty()) {
130	    res.error = err;
131	  } else {
132	    for (size_t i = 0; i < argvs.size(); ++i) {
133	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
134	      if (r.spawn_failed) {
135	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
136	        break;
137	      }
138	      if (r.timed_out) {
139	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
140	                    std::to_string(opts.timeout_ms) + " ms";
141	        break;
142	      }
143	      if (r.rc != opts.expect_rc) {
144	        res.error = "plan step " + std::to_string(i) + ": expected exit " +
145	                    std::to_string(opts.expect_rc) + ", got " +
146	                    std::to_string(r.rc);
147	        break;
148	      }
149	      const StateFile sf = read_state_file(state_path(wd, i));
150	      if (!sf.ok()) {
151	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
152	        break;
153	      }
154	      res.phases.push_back({sf.st.mcycle, sf.st.minstret});
155	    }
156	  }
157	
158	  fs::remove_all(wd, ec);
159	  if (own_mmap) ::unlink(mmap_path.c_str());
160	  return res;
